module tb_TopModule;
    logic        in;
    logic [9:0]  state;
    logic [9:0]  next_state;
    logic        out1;
    logic        out2;

    TopModule dut (
        .in(in),
        .state(state),
        .next_state(next_state),
        .out1(out1),
        .out2(out2)
    );

    initial begin
        integer i, s;
        // Test all single-hot states with in = 0 and in = 1
        for (s = 0; s < 10; s++) begin
            for (i = 0; i < 2; i++) begin
                in = i[0];
                state = (1 << s);
                #1;
                // Verify expected outputs and next states based on specification
                case (s)
                    0: begin
                        if (out1 !== 0 || out2 !== 0) $fatal(1, "S0 output error");
                        if (in == 0 && next_state !== 10'b0000000001) $fatal(1, "S0->0 next_state error");
                        if (in == 1 && next_state !== 10'b0000000010) $fatal(1, "S0->1 next_state error");
                    end
                    1: begin
                        if (out1 !== 0 || out2 !== 0) $fatal(1, "S1 output error");
                        if (in == 0 && next_state !== 10'b0000000001) $fatal(1, "S1->0 next_state error");
                        if (in == 1 && next_state !== 10'b0000000100) $fatal(1, "S1->1 next_state error");
                    end
                    2: begin
                        if (out1 !== 0 || out2 !== 0) $fatal(1, "S2 output error");
                        if (in == 0 && next_state !== 10'b0000000001) $fatal(1, "S2->0 next_state error");
                        if (in == 1 && next_state !== 10'b0000001000) $fatal(1, "S2->1 next_state error");
                    end
                    3: begin
                        if (out1 !== 0 || out2 !== 0) $fatal(1, "S3 output error");
                        if (in == 0 && next_state !== 10'b0000000001) $fatal(1, "S3->0 next_state error");
                        if (in == 1 && next_state !== 10'b0000010000) $fatal(1, "S3->1 next_state error");
                    end
                    4: begin
                        if (out1 !== 0 || out2 !== 0) $fatal(1, "S4 output error");
                        if (in == 0 && next_state !== 10'b0000000001) $fatal(1, "S4->0 next_state error");
                        if (in == 1 && next_state !== 10'b0000100000) $fatal(1, "S4->1 next_state error");
                    end
                    5: begin
                        if (out1 !== 0 || out2 !== 0) $fatal(1, "S5 output error");
                        if (in == 0 && next_state !== 10'b0100000000) $fatal(1, "S5->0 next_state error");
                        if (in == 1 && next_state !== 10'b0001000000) $fatal(1, "S5->1 next_state error");
                    end
                    6: begin
                        if (out1 !== 0 || out2 !== 0) $fatal(1, "S6 output error");
                        if (in == 0 && next_state !== 10'b1000000000) $fatal(1, "S6->0 next_state error");
                        if (in == 1 && next_state !== 10'b10000000) $fatal(1, "S6->1 next_state error");
                    end
                    7: begin
                        if (out1 !== 0 || out2 !== 1) $fatal(1, "S7 output error");
                        if (in == 0 && next_state !== 10'b0000000001) $fatal(1, "S7->0 next_state error");
                        if (in == 1 && next_state !== 10'b10000000) $fatal(1, "S7->1 next_state error");
                    end
                    8: begin
                        if (out1 !== 1 || out2 !== 0) $fatal(1, "S8 output error");
                        if (in == 0 && next_state !== 10'b0000000001) $fatal(1, "S8->0 next_state error");
                        if (in == 1 && next_state !== 10'b0000000010) $fatal(1, "S8->1 next_state error");
                    end
                    9: begin
                        if (out1 !== 1 || out2 !== 1) $fatal(1, "S9 output error");
                        if (in == 0 && next_state !== 10'b0000000001) $fatal(1, "S9->0 next_state error");
                        if (in == 1 && next_state !== 10'b0000000010) $fatal(1, "S9->1 next_state error");
                    end
                endcase
            end
        end

        // Test multi-state combination (e.g., S4 and S2)
        in = 1'b1;
        state = 10'b0000010100; // S2 and S4
        #1;
        // S2->1 gives S3 (0000001000), S4->1 gives S5 (0001000000). Combined next_state should be S3 | S5 = 10'b0001001000.
        if (next_state !== 10'b0001001000) $fatal(1, "Multi-state next_state error");

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

